// Bring in the Verus prelude
use verus::prelude::*;

verus! {
    /// Computes the largest proper divisor of an 8‐bit signed integer n > 1.
    ///
    /// Returns d such that
    ///   1 ≤ d < n
    ///   n % d = 0
    ///   for every k with d < k < n, n % k ≠ 0
    #[verifier(nonlinear)]
    fn largest_divisor(n: i8) -> i8
        requires n > 1
        ensures  1 <= result && result < n
        ensures  n % result == 0
        ensures  forall |k: i8| result < k && k < n ==> n % k != 0
    {
        // We will scan all i from 1 up to n−1,
        // keeping track of the largest divisor seen so far.
        let mut i:    i8 = 1;
        let mut maxd: i8 = 1;

        // Loop invariant:
        //   1) 1 ≤ maxd < n
        //   2) 1 ≤ i ≤ n
        //   3) For every k in [1, i), if k divides n then k ≤ maxd.
        // At termination i == n, so maxd is the maximal divisor < n.
        while i < n
            invariant 1 <= maxd && maxd < n
            invariant 1 <= i    && i <= n
            invariant forall |k: i8|
                       1 <= k && k < i ==>
                       (n % k == 0).implies(k <= maxd)
            decreases n - i
        {
            if n % i == 0 {
                // i divides n; update maxd if i is larger
                if i > maxd {
                    maxd = i;
                }
            }
            i += 1;
        }

        // By the final invariant, maxd is the largest divisor of n in [1, n).
        maxd
    }
}